# ---------------------------------------------------------------------------
# The home page reads its own content from the server.
#
# Packages, the headline numbers, the FAQ, the testimonials and every line of
# text on the page are editable from the operations site. Two of the page's own
# bindings have to change first: they attach handlers to elements that the
# content loader replaces, and a handler on a replaced element is a button that
# does nothing.
# ---------------------------------------------------------------------------

patch("index.html", "hand the checkout price list out of its closure",
      """/* --------------------------------------------------------- sending a form ---""",
      """/* The content loader at the end of this page repaints the package cards when
   the office edits them, and it has to reprice the checkout sheet at the same
   moment \u2014 the sheet reads D.packages, not the card. D is declared inside this
   IIFE, so it cannot be reached from out there unless it is handed out
   deliberately. One named function rather than exposing D wholesale: the
   loader may replace the price list and nothing else. */
window.__glovelsSetPackages = function (list) {
  if (Array.isArray(list) && list.length) D.packages = list;
};

/* --------------------------------------------------------- sending a form ---""")

patch("index.html", "package tabs keep working after a repaint",
      """$$('[data-ptab]').forEach(t => t.onclick = () => {
  $$('[data-ptab]').forEach(o => o.setAttribute('aria-selected','false'));
  t.setAttribute('aria-selected','true');
  $$('.pane').forEach(p => p.classList.toggle('active', p.dataset.pane === t.dataset.ptab));
});""",
      """/* Delegated, not bound per button: the packages section is rebuilt from
   /api/content when the office edits it, and a handler attached to the old
   button goes with the old button. */
document.addEventListener('click', e => {
  const t = e.target.closest('[data-ptab]');
  if (!t) return;
  $$('[data-ptab]').forEach(o => o.setAttribute('aria-selected','false'));
  t.setAttribute('aria-selected','true');
  $$('.pane').forEach(p => p.classList.toggle('active', p.dataset.pane === t.dataset.ptab));
});""")

patch("index.html", "Choose-a-package keeps working after a repaint",
      """let buying = null;
$$('[data-buy]').forEach(b => b.onclick = () => {
  resetSheet();
  buying = D.packages.find(p => p.id === b.dataset.buy);""",
      """let buying = null;
/* Delegated for the same reason as the tabs above. `D.packages` is refreshed by
   the content loader at the same moment the cards are, so the price in this
   sheet and the price on the card are the same number. */
document.addEventListener('click', e => {
  const b = e.target.closest('[data-buy]');
  if (!b) return;
  resetSheet();
  buying = D.packages.find(p => p.id === b.dataset.buy);
  if (!buying) return;""")

# The loader itself, at the very end of the body, after the page's own scripts
# have run and defined D.
#
# REPLACED, not skipped-if-present. index.html persists between builds, so a
# guard that only ever adds leaves whatever version of the loader was written
# the first time — and the loader is the thing that repaints the cards, the
# prices and the packages from the server. An edit to content_client.py that
# never reaches the page is the worst kind of change: the file says one thing
# and the site does another.
# The stamp comment sits between <script> and the loader's own banner, so
# the pattern has to allow it — the first version did not, and the refresh
# silently stopped matching the moment it had run once.
_loader = re.compile("<script>\\s*(?:/\\* content_client [0-9a-f]+ \\*/\\s*)?"
                     "/\\*[-\\s]*\\n\\s*Glovels \u2014 live content.*?</script>\\n",
                     re.S)
_page = HERE / "index.html"
_html = _page.read_text(encoding="utf-8")
#
# Compared by FINGERPRINT, not by text. Four later patches edit the loader in
# place, so the copy on the page is never byte-identical to the source — and a
# plain comparison replaced it on every single run, undoing those four and
# re-applying them, for ever. The stamp says which version of
# content_client.py the page was built from; equal means leave it alone.
_stamp = hashlib.sha256(content_client.SCRIPT.encode("utf-8")).hexdigest()[:12]
_fresh = ("<script>\n/* content_client " + _stamp + " */\n"
          + content_client.SCRIPT.strip() + "\n</script>\n")
_found = _loader.search(_html)
if _found:
    if ("/* content_client " + _stamp + " */") in _found.group(0):
        skipped.append("index.html: the live content loader")
    else:
        write(_page, _html.replace(_found.group(0), _fresh, 1))
        applied.append("index.html: the live content loader (content_client.py changed)")
else:
    patch("index.html", "the live content loader",
          "</body>",
          _fresh + "</body>",
          marker="Glovels \u2014 live content")


# The message when the server cannot be reached said the server was not running,
