# ---------------------------------------------------------------- index.html
#
# The studio writes on the server now.
#
# What was here: four hard-coded sentences with two slots, filled from the chips
# and printed. It always produced the same paragraph for the same picks — the
# "Write it again" button regenerated byte-identical text, which is the first
# thing anyone tries — and the wording could only be changed by editing the page.
#
# What replaces it: a POST to /api/ai/draft. The wording lives in the `writing`
# content block, so the office rewrites it from the operations site; each press
# of "write it again" asks for the next pass and gets different sentences; and a
# student who is signed in has the draft saved to their account, where their
# counsellor can see it — which matters, because the thing being sold on the
# next line is a human rewrite of exactly this draft.
#
# The chips come from /api/ai/chips for the same reason. The baked-in AI block
# stays as the fallback for a page opened from disk with no server behind it.
STUDIO = r"""
/* ------------------------------------------------- the studio, server-side */
let AI_CHIPS = null;
let aiPass = 0;

async function aiChips(kind) {
  if (!AI_CHIPS) {
    try {
      const r = await fetch('/api/ai/chips', {credentials: 'same-origin'});
      if (r.ok) AI_CHIPS = await r.json();
    } catch (e) { /* opened from disk, or the server is down */ }
  }
  if (AI_CHIPS && AI_CHIPS[kind]) return AI_CHIPS[kind];
  /* The page's own copy. Same keys, so a draft asked for with these still
     matches the bank on the server. */
  return kind === 'sop'
    ? {signals: AI['SOP signal'] || [], motives: AI['SOP motive'] || []}
    : {signals: AI['LOR signal'] || []};
}

async function aiDraft(kind, out) {
  const picked = g => $$('[data-chip][data-group="' + g + '"][aria-pressed="true"]')
    .map(b => b.dataset.chip);
  const sigs = picked('sig');
  if (!sigs.length) {
    out.innerHTML = '<div class="warnbox" style="border-color:#c0392b;background:#fdf3f2;'
      + 'color:#7a2118">' + (kind === 'sop'
        ? 'Pick at least one thing for the draft to draw on.'
        : 'Pick at least one thing the referee actually saw.') + '</div>';
    return;
  }

  const val = id => { const el = $('#' + id); return el ? el.value.trim() : ''; };
  out.innerHTML = '<div class="ai-draft"><div class="steps-lbl">Writing…</div>'
    + '<p style="opacity:.6">One moment.</p></div>';

  let d;
  try {
    const r = await fetch('/api/ai/draft', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      credentials: 'same-origin',
      body: JSON.stringify({
        kind: kind,
        programme: val('aiProg'), university: val('aiUni'),
        signals: sigs, motives: picked('mot'),
        who: val('aiWho'), span: val('aiSpan'), instance: val('aiInst'),
        pass: aiPass,
      }),
    });
    d = await r.json();
    if (!r.ok) throw new Error(d.error || 'The studio could not write that just now.');
  } catch (err) {
    out.innerHTML = '<div class="warnbox" style="border-color:#c0392b;background:#fdf3f2;'
      + 'color:#7a2118">' + esc(err.message) + '</div>';
    return;
  }

  const draft = d.draft;
  out.innerHTML =
      '<div class="ai-draft"><div class="steps-lbl">Draft '
    + (aiPass === 0 ? 'one' : String(aiPass + 1)) + ' · ' + draft.words + ' words</div>'
    + draft.paragraphs.map(t => '<p>' + esc(t) + '</p>').join('')
    + '</div>'
    + '<div class="warnbox" style="margin-top:12px"><b>This is a draft, not a submission.</b> '
    + 'It uses only what you entered — no invented grade, title or publication. An '
    + 'admissions writer rewrites it with you before it goes anywhere, and that review is what '
    + 'you are paying for.</div>'
    + (d.saved
        ? '<p style="font-size:11.6px;color:var(--green);margin:10px 0 0;font-weight:600">'
          + 'Saved to your account — it is in your dashboard, and your counsellor can see it.</p>'
        : '<p style="font-size:11.6px;color:var(--muted);margin:10px 0 0">'
          + 'Sign in before you write and every draft is kept in your dashboard.</p>')
    + '<div class="paid-cta"><button class="btn btn-primary" id="aiBuy">Add the '
    + (kind === 'sop' ? 'SOP' : 'LOR') + ' rewrite to my plan</button>'
    + '<button class="btn btn-ghost" id="aiCopy">Copy</button>'
    + '<button class="btn btn-ghost" id="aiAgain">Write it again</button></div>';

  $('#aiAgain').onclick = () => { aiPass++; aiDraft(kind, out); };
  $('#aiCopy').onclick = () => {
    const text = draft.paragraphs.join('\n\n');
    const done = () => { $('#aiCopy').textContent = 'Copied'; };
    if (navigator.clipboard) navigator.clipboard.writeText(text).then(done, () => {});
    else {
      const ta = document.createElement('textarea');
      ta.value = text; document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); done(); } catch (e) {}
      ta.remove();
    }
  };
  $('#aiBuy').onclick = () => {
    const svc = SERVICES.find(s => s.ai === kind);
    if (svc) { chosen.add(svc.id); render(); plan(); }
    $('#aiModal').classList.remove('on');
    document.getElementById('services').scrollIntoView({behavior: 'smooth', block: 'start'});
  };
}
"""

