# ------------------------------------------------------------ every page
#
# The corner of the screen.
#
# On a marketing page: a green WhatsApp button, because that is the one an
# Indian family will actually press, with the site's own chat under it in a
# quieter weight. The chat is kept rather than dropped because it asks for a
# name and a number before the first message — which is what makes it a lead in
# the enquiry book. A WhatsApp conversation lives in WhatsApp and never reaches
# the operations site; that is the trade, made on purpose.
#
# On a portal screen: the chat only, opening the student's real thread with
# their counsellor, on whatever screen they are on. No WhatsApp — they are past
# the point of being sold to — and no intro form, because the server already
# knows who they are.
#
# messages.html is excluded: that screen IS the thread, and a floating button
# over it offering to open the thread is furniture.
import chat_widget

PORTAL_PAGES = {
    "dashboard.html", "documents.html", "profile.html",
    "applications.html", "universities.html", "scholarships.html",
    # visa.html and services.html were both missed when they were added, so a
    # signed-in student reading their own visa file — or the services they
    # have already bought — was shown the marketing corner: WhatsApp, an intro
    # form asking a name we already hold, and a line selling what they own.
    "visa.html", "services.html",
}

# Never gets a corner: the staff screens (they have the Website chat screen),
# the sign-in page, the 404, and the thread itself.
#
# These two sets are the kind that go stale silently: a page added later gets
# neither name, falls through to "site", and quietly carries the public chat
# widget. That is exactly what happened to leads, blog-admin and partner —
# hence the guard underneath, which refuses to build rather than let it happen
# again.
NO_CORNER = {
    "messages.html", "login.html", "404.html",
    "counsellor.html", "admin.html", "home.html", "catalogue.html", "chat.html",
    "leads.html", "blog-admin.html",
    # A partner is not a visitor to be sold to and has no chat at all — the
    # brief said so plainly. The widget also greets in our name, which on a
    # white-labelled screen is the one word that must not appear.
    "partner.html",
}

# The guard itself. A page built on the portal shell is behind a login by
# definition, so it must never fall through to the public "site" widget. This
# reads the built page rather than a hand-kept list, which is the whole point:
# the next screen somebody adds cannot forget to join a set.
def must_not_be_public(name, markup, mode):
    if mode == "site" and 'class="p-shell"' in markup:
        raise SystemExit(
            "apply_fixes: " + name + " is a signed-in screen but would get the "
            "public chat widget. Add it to PORTAL_PAGES (a student screen) or "
            "NO_CORNER (staff, or a screen with no chat at all)."
        )


def chat_everywhere():
    n = 0
    for f in sorted(list(HERE.glob("*.html")) + list((HERE / "post").glob("*.html"))):
        if f.name in NO_CORNER:
            continue
        mode = "portal" if f.name in PORTAL_PAGES else "site"

        t = f.read_text(encoding="utf-8")
        if "</body>" not in t:
            continue
        must_not_be_public(f.name, t, mode)

        block = ('<script>window.__glovelsChatMode="' + mode + '";</script>\n'
                 + '<script>' + chat_widget.WIDGET + "</script>\n")

        # Already there: replace it rather than skip. The widget changes, and a
        # patch that only ever adds leaves forty pages carrying whichever
        # version happened to be current the day they were generated.
        i = t.find("<script>window.__glovelsChatMode")
        if i < 0:
            i = t.find("<script>\n/* GLOVELS-CHAT-WIDGET */")
        if i < 0:
            i = t.find("<script>/* GLOVELS-CHAT-WIDGET */")
        if i >= 0:
            j = t.index("</script>", t.index("/* GLOVELS-CHAT-WIDGET */", i)) + len("</script>")
            new_t = t[:i] + block.rstrip("\n") + t[j:]
            if new_t == t:
                continue
            write(f, new_t)
        else:
            write(f, t.replace("</body>", block + "</body>", 1))
        n += 1
    if n:
        applied.append(f"{n} page(s): the corner \u2014 WhatsApp on the site, chat in the portal")
    else:
        skipped.append("every page: the corner")


chat_everywhere()


# ---------------------------------------------------------------- every page
#
# `hidden` has to mean hidden.
#
# The browser hides [hidden] with `display:none` from its own stylesheet, which
# is the weakest rule there is: ANY class that sets `display` beats it. This
# has now bitten four separate things in this codebase — the notifications dot,
# the bulk-action bar, the chat button, and a red "Lock again" button that sat
# in the results header of every visitor's first view offering to re-lock
# universities they had never unlocked.
#
# It is not a mistake anyone stops making, because the markup reads correctly:
# `<button hidden class="pill">` is exactly what you would write. So the rule is
# made to win instead. This is what normalize.css does, and the `!important` is
# the point of it — without that it loses to the next `.pill{display:flex}`
# somebody adds.
HIDDEN_RULE = """<style>/* GLOVELS-HIDDEN-RULE */
[hidden]{display:none !important}
</style>
"""


def hidden_means_hidden():
    n = 0
    for f in sorted(list(HERE.glob("*.html")) + list((HERE / "post").glob("*.html"))):
        t = f.read_text(encoding="utf-8")
        if "GLOVELS-HIDDEN-RULE" in t or "</head>" not in t:
            continue
        write(f, t.replace("</head>", HIDDEN_RULE + "</head>", 1))
        n += 1
    if n:
        applied.append(f"{n} page(s): hidden means hidden")
    else:
        skipped.append("every page: hidden means hidden")


hidden_means_hidden()


# ---------------------------------------------------------------- index.html
#
# The entry requirements come from the server.
#
# `C` is the country map the finder reads: the CGPA bar it scores against, and
# every line in the Requirements panel a student opens before deciding whether
# they qualify. It was baked into the page, so the funds figure a visa officer
# wants — which changes every year, and differs per country — could only be
# corrected by a developer editing index.html and redeploying.
#
# The same escape-hatch shape as the packages and the showcase: the IIFE hands
# out one named setter, and the loader that already fetches /api/catalogue calls
# it with the destinations that came back.
# There are two country maps on this page, in two IIFEs that cannot see each
# other. `D.countries` is the one the Requirements panel and the CGPA scoring
# read — it is aliased as `C` on line 1268 — and the second block has its own
# `C` for the showcase. Patching only the second one made the panel keep showing
# the numbers the page shipped with while the site reported the edit as saved,
# which is the worst of both.
patch(
    "index.html",
    "the Requirements panel's own country map can be replaced too",
    "window.__glovelsSetPackages = function (list) {\n  if (Array.isArray(list) && list.length) D.packages = list;\n};",
    """window.__glovelsSetPackages = function (list) {
  if (Array.isArray(list) && list.length) D.packages = list;
};

/* The entry requirements. `C` on the line below is this same object, so
   mutating it in place is what makes the Requirements panel, the CGPA scoring
   and the destination cards all read the edited figures. Replacing
   `D.countries` with a new object would leave `C` pointing at the old one. */
window.__glovelsSetCountryFacts = function (map) {
  if (!map || typeof map !== 'object') return;
  Object.keys(map).forEach(function (code) {
    var here = D.countries[code];
    if (!here) return;
    var live = map[code];
    Object.keys(live).forEach(function (k) {
      /* null and undefined mean "the server has nothing to say about this",
         which is not "empty" — copying them would blank a line the page
         shipped with. */
      if (live[k] !== undefined && live[k] !== null) here[k] = live[k];
    });
  });
};""",
    # A marker unique to the DEFINITION. The obvious one — the function's own
    # name — is also in the loader ten lines below, so once the loader had been
    # patched this one reported itself as already applied and silently did
    # nothing, while the site went on showing the numbers it shipped with.
    marker="mutating it in place is what makes the Requirements panel",
)

patch(
    "index.html",
    "the finder's country facts can be replaced from the server",
    "window.__glovelsSetCatalogue = function (list) {",
    """window.__glovelsSetCountries = function (map) {
  if (!map || typeof map !== 'object') return;
  Object.keys(map).forEach(function (code) {
    if (!C[code]) return;              /* a destination this page never had */
    var live = map[code];
    Object.keys(live).forEach(function (k) {
      /* Undefined means "the server has nothing to say about this", which is
         not the same as "empty". Copying it would blank a line the page shipped
         with, and the first anyone would know is a student asking why the
         requirements panel is missing the funds figure. */
      if (live[k] !== undefined && live[k] !== null) C[code][k] = live[k];
    });
  });
  render();
};

window.__glovelsSetCatalogue = function (list) {""",
    marker="__glovelsSetCountries",
)

